import {albums,members,roles} from './data.js';
import {rankMembers,sharedAlbums} from './matching.js';
const key='slug-collective-demo-v1';
const defaults=()=>({joined:false,profile:{name:'',bio:'',favorites:[],roles:[],intent:'',provider:''},conversations:{}});
let state;try{state=JSON.parse(localStorage.getItem(key))||defaults();if(!state.profile||!Array.isArray(state.profile.favorites)||!state.conversations)state=defaults();}catch{state=defaults();}
let tab='people',filter='All people',query='',activeChat=null,step=0;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={people:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2m2-15a3 3 0 0 1 0 6m1 3a6 6 0 0 1 3 6"/>',create:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',inbox:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-9.5A8.5 8.5 0 0 1 10.5 4H13a8 8 0 0 1 8 7.5Z"/><path d="M7 10h9M7 14h6"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',send:'<path d="m3 3 18 9-18 9 4-9-4-9Zm4 9h14"/>',link:'<path d="m9 15 6-6m-7 4-2 2a4 4 0 0 0 6 6l3-3m1-7 2-2a4 4 0 0 0-6-6L9 6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.create}</svg>`;};
const brand=()=>`<a class="brand" href="#" data-action="home" aria-label="Slug Collective home"><svg class="slug" viewBox="0 0 50 40" aria-hidden="true"><path d="M7 30c5-1 7-4 10-10 3-7 9-10 16-7 5 2 7 8 7 13l5 4c-9 5-30 7-38 0Z" fill="currentColor" stroke="none"/><path d="m31 14-1-8m7 10 3-8"/><circle cx="30" cy="5" r="2" fill="currentColor"/><circle cx="41" cy="7" r="2" fill="currentColor"/></svg><span>slug collective<small>A LITTLE CLOSER.</small></span></a>`;
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Browser storage is unavailable. Changes will last for this visit.');}}
let toastTimer;function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('toast-visible'),3200);}
function artwork(id,cls=''){const a=albums[id];return `<img class="${cls}" src="${a.art}" alt="Original demo artwork for ${esc(a.title)}" loading="lazy">`;}
function picker(){return `<div class="album-picker">${albums.map(a=>`<button type="button" class="pick ${state.profile.favorites.includes(a.id)?'selected':''}" data-action="album" data-id="${a.id}" aria-pressed="${state.profile.favorites.includes(a.id)}" aria-label="Select ${esc(a.title)} by ${esc(a.artist)}">${artwork(a.id)}<span>${esc(a.title)}<br><span class="muted">${esc(a.artist)}</span></span></button>`).join('')}</div>`;}
function onboarding(){app.innerHTML=`<div class="onboard"><section class="onboard-story">${brand()}<div><div class="eyebrow">SANTA CRUZ SOUNDS BETTER TOGETHER</div><h1>A little shared taste.<br><em>A lot of possibility.</em></h1><p class="sub">Meet the people behind the headphones. Find someone to make something with.</p><div class="art-stack">${artwork(0)}${artwork(2)}${artwork(4)}</div></div><p class="small muted">An independent creative space for the Slug Collective.</p></section><section class="onboard-form"><div class="steps" aria-label="Step ${step+1} of 3">${[0,1,2].map(n=>`<i class="${n<=step?'active':''}"></i>`).join('')}</div>${step===0?`<div class="eyebrow">YOUR PEOPLE ARE HERE</div><h2>Come hang.</h2><p class="muted">Good music. New faces. No perfect profile required.</p><form id="name-form"><label for="name">What should we call you?</label><input class="field" id="name" name="name" required maxlength="40" autocomplete="given-name" placeholder="Your first name" value="${esc(state.profile.name)}"><button class="primary" type="submit">Let’s go ${icon('arrow')}</button></form><p class="small muted">Interactive demo · no account or email needed.</p>`:step===1?`<div class="eyebrow">HEY, ${esc(state.profile.name)}</div><h2>Bring your music.</h2><p class="muted">Give people something to say “wait, you too?” about.</p><button class="provider" data-action="provider" data-provider="Spotify">${icon('music')} Connect Spotify <span>↗</span></button><button class="provider" data-action="provider" data-provider="Apple Music">${icon('music')} Connect Apple Music <span>↗</span></button><p class="small muted">Demo connections only. No sign-in or listening data is requested. We’ll use sample favorites.</p><button class="primary" data-action="choose">I’ll pick a few favorites ${icon('arrow')}</button><button class="text-button" data-action="join">Skip for now — just let me explore</button><br><button class="text-button" data-action="back-onboard">Back</button>`:`<div class="eyebrow">A LITTLE INTRO THROUGH MUSIC</div><h2>What’s on repeat?</h2><p class="small muted">Pick any favorites. You can change these later.</p>${picker()}<button class="primary" data-action="join">Find my people ${icon('arrow')}</button><button class="text-button" data-action="back-onboard">Back</button>`}</section></div>`;}
function render(){if(!state.joined){onboarding();return;}app.innerHTML=`<aside class="sidebar">${brand()}<nav aria-label="Main navigation">${[['people','People'],['create','Create'],['inbox','Inbox'],['profile','Profile']].map(([id,label])=>`<button class="nav ${tab===id?'active':''}" data-action="tab" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-foot"><span class="live-dot"></span>A small world. Good company.<br>Santa Cruz, California<div class="mini-profile"><span class="initial">${esc(state.profile.name[0]?.toUpperCase()||'S')}</span><span>${esc(state.profile.name)}<br><span class="small muted">Member of the collective</span></span></div></div></aside><div class="shell"><header class="topbar"><span>THE SLUG COLLECTIVE <span style="margin:0 12px;color:#505744">/</span> <b>${{people:'Find your people',create:'Make something together',inbox:'Keep the conversation going',profile:'Your little corner'}[tab]}</b></span><div class="mobile-brand">${brand()}</div><span class="demo-badge">DEMO · FICTIONAL MEMBERS</span></header><main id="main">${tab==='people'||tab==='create'?discovery():tab==='inbox'?inbox():profile()}</main></div>`;}
function discovery(){const create=tab==='create';return `<section class="hero"><div class="eyebrow"><span class="live-dot"></span>${create?'GOOD THINGS START WITH “WHAT IF?”':'YOUR NEXT “WAIT, YOU TOO?”'}</div><h1>${create?'Make a little<br><em>something together.</em>':'Find your frequency.<br><em>Find your people.</em>'}</h1><p class="sub">${create?'A voice for your demo. A lens for your vision. Someone to figure it out with.':'Familiar albums. Unfamiliar faces. A whole collective of people worth saying hey to.'}</p><div class="hero-art"><span class="record-label">${create?'less planning. more making.':'good taste, good company.'}</span><div class="record"></div></div></section><div class="toolbar"><div class="filters" aria-label="${create?'Creative role':'People'} filters">${(create?['All creatives','Production','Vocals','Photography','Design','Film']:['All people','Shared taste','Something new']).map(f=>`<button class="chip ${filter===f?'active':''}" data-action="filter" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}${create?`<select id="role-filter" aria-label="More creative roles"><option value="">More roles</option>${roles.filter(r=>!['Production','Vocals','Photography','Design','Film'].includes(r)).map(r=>`<option ${filter===r?'selected':''}>${r}</option>`).join('')}</select>`:''}</div><label class="search" style="margin:0">${icon('search')}<input id="search" type="search" placeholder="${create?'Search people, skills…':'People, artists, albums…'}" aria-label="Search ${create?'creatives':'members'}" value="${esc(query)}"></label></div><div id="results">${results()}</div><p class="footer-note">A little curiosity goes a long way. Say hey.<br>Fictional profiles · Original demo artwork · Independent of UC Santa Cruz</p>`;}
function visible(){return rankMembers(members,state.profile,tab).filter(m=>{if(tab==='people'&&filter==='Shared taste'&&!m.shared.length)return false;if(tab==='people'&&filter==='Something new'&&m.shared.length)return false;if(tab==='create'&&filter!=='All creatives'&&!m.roles.includes(filter))return false;return [m.name,...m.roles,m.intent,...m.albums.flatMap(id=>[albums[id].title,albums[id].artist])].join(' ').toLowerCase().includes(query.toLowerCase().trim());});}
function results(){const list=visible();return `<div class="section-label">${query?'Search results':filter.startsWith('All')?'A few faces from the collective':esc(filter)}<span>${list.length} ${tab==='create'?'creatives':'people'} · ${tab==='create'?'open to possibilities':'curated for you'}</span></div><div class="grid">${list.length?list.map(card).join(''):`<div class="empty"><h2>${filter==='Shared taste'&&!state.profile.favorites.length?'Your music starts the connection.':'No faces here just yet.'}</h2><p>${filter==='Shared taste'&&!state.profile.favorites.length?'Add a few favorites to find your shared taste.':'Try a different search or open things up a little.'}</p><button class="secondary" data-action="${filter==='Shared taste'&&!state.profile.favorites.length?'edit-profile':'clear'}">${filter==='Shared taste'&&!state.profile.favorites.length?'Add favorites':'Clear filters'}</button></div>`}</div>`;}
function reason(m){if(tab==='create'&&m.complements.length)return `Your ${m.pairs[0].yours.toLowerCase()} + their ${m.pairs[0].theirs.toLowerCase()}`;if(m.shared.length){const a=albums[m.shared[0]];return `You both listen to ${a.artist}`;}return tab==='create'?'Open to making something new':'A new sound for your orbit';}
function card(m){const a=albums[m.albums[0]],create=tab==='create';return `<article class="card"><div class="card-top"><img class="avatar" src="${m.avatar}" alt="Illustrated portrait of ${m.name}" loading="lazy"><button class="identity" data-action="member" data-id="${m.id}"><strong>${m.name}</strong><small>${m.pronouns} · ${m.college}</small></button><button class="arrow" data-action="member" data-id="${m.id}" aria-label="View ${m.name}'s profile">${icon('arrow')}</button></div>${create?'':`<div class="album-wrap">${artwork(a.id)}<div class="album-tag">${icon('music')} ON REPEAT</div></div>`}<div class="card-body">${create?`<div class="role-tags">${m.roles.map(r=>`<span class="role-tag">${r}</span>`).join('')}</div><p class="intent">“${esc(m.intent)}”</p>${m.work?`<button class="work-preview" data-action="work" data-id="${m.id}">${artwork(m.albums[0])}<span>${m.work}<small>Explore a work concept</small></span>${icon('arrow')}</button>`:`<div class="work-preview muted">A work in progress. Just like the rest of us.</div>`}`:`<h2 class="album-title">${a.title}</h2><p class="artist">${a.artist}</p>`}<div class="shared">${icon(create?'create':'link')}<span>${esc(reason(m))}</span></div><button class="say" data-action="hey" data-id="${m.id}" data-context="${esc(create?(m.work||m.intent):`${a.title} by ${a.artist}`)}">Say hey ${icon('inbox')}</button></div></article>`;}
function openMember(id){const m=members[id];modal.setAttribute('aria-label',m.name+' profile');modal.innerHTML=`<button class="close" data-action="close" aria-label="Close profile">${icon('close')}</button><div class="modal-profile"><img class="avatar" src="${m.avatar}" alt="Illustrated portrait"><div><h2>${m.name}</h2><span class="small muted">${m.pronouns} · ${m.college}</span></div></div><p>${esc(m.bio)}</p><div class="role-tags">${m.roles.map(r=>`<span class="role-tag">${r}</span>`).join('')}</div><p class="small muted">ON REPEAT</p><div class="modal-albums">${m.albums.map(id=>`<div>${artwork(id)}<p>${albums[id].title}<br><span class="muted">${albums[id].artist}</span></p></div>`).join('')}</div><p class="small muted">OPEN TO</p><p>${m.intent}</p>${m.work?`<button class="work-preview" data-action="work" data-id="${m.id}">${artwork(m.albums[0])}<span>${m.work}<small>Explore a work concept</small></span>${icon('arrow')}</button>`:''}<button style="margin-top:20px;width:100%" class="primary" data-action="hey" data-id="${m.id}" data-context="${esc(tab==='create'?(m.work||m.intent):albums[m.albums[0]].title)}">Say hey ${icon('inbox')}</button>`;modal.showModal();}
function openWork(id){const m=members[id];modal.setAttribute('aria-label',m.work+' work concept');modal.innerHTML=`<button class="close" data-action="close" aria-label="Close work preview">${icon('close')}</button><p class="eyebrow">WORK CONCEPT · ${m.name}</p>${artwork(m.albums[0],'work-art')}<h2>${m.work}</h2><p>${m.workDescription}</p><p class="small muted">This prototype shows a fictional work concept. Audio, video, and file uploads will come in a later version.</p><button class="primary" data-action="hey" data-id="${m.id}" data-context="${esc(m.work)}">Ask about this ${icon('inbox')}</button>`;if(!modal.open)modal.showModal();}
function startChat(id,context){const old=state.conversations[id];if(!old)state.conversations[id]={context,messages:[]};else if(context)old.context=context;activeChat=id;tab='inbox';save();modal.close();render();document.querySelector('#message')?.focus();}
function inbox(){const entries=Object.entries(state.conversations);if(activeChat===null&&entries.length)activeChat=Number(entries[0][0]);const m=members[activeChat],c=state.conversations[activeChat];return `<div class="eyebrow">A SMALL HELLO GOES A LONG WAY</div><h1>Keep it <em>going.</em></h1><p class="sub" style="margin-bottom:28px">Your conversations, all in one place. Demo messages stay in this browser.</p>${!entries.length?`<div class="empty"><h2>Every good friendship starts somewhere.</h2><p>Find an album you love. Say hey to the person behind it.</p><button class="primary" data-action="tab" data-tab="people">Meet the collective ${icon('arrow')}</button></div>`:`<div class="inbox-layout"><div class="threads" aria-label="Conversations">${entries.map(([id,v])=>`<button class="thread ${Number(id)===activeChat?'active':''}" data-action="thread" data-id="${id}"><img class="avatar" src="${members[id].avatar}" alt=""><span>${members[id].name.split(' ')[0]}<small>${esc(v.messages.at(-1)?.text||'Start with a little hello')}</small></span></button>`).join('')}</div><section class="chat" aria-label="Conversation with ${m.name}"><div class="chat-head"><strong>${m.name}</strong><small>Simulated conversation · replies are generated from fixed demo text</small></div><div class="messages" aria-live="polite"><div class="context">Talking about: ${esc(c.context)}</div>${!c.messages.length?`<p class="small muted">You could start with “Your taste is so good — how did you find this?”</p>`:c.messages.map(v=>`<div class="message ${v.from==='me'?'me':''}"><span class="sr-only">${v.from==='me'?'You':m.name}: </span>${esc(v.text)}</div>`).join('')}</div><form class="compose" id="message-form"><input id="message" aria-label="Message ${m.name}" placeholder="Say something nice…" required maxlength="1000" autocomplete="off"><button class="primary" type="submit" aria-label="Send message">${icon('send')}</button></form></section></div>`}`;}
function profile(){return `<div class="eyebrow">NO PERFECT PROFILE REQUIRED</div><h1>Your little <em>corner.</em></h1><p class="sub">A few things that make it easier to find your people.</p><form id="profile-form" class="profile-form"><label for="profile-name">Your name</label><input id="profile-name" class="field" name="name" required maxlength="40" value="${esc(state.profile.name)}"><label for="bio">A little about you</label><textarea id="bio" name="bio" class="field" maxlength="300" placeholder="Probably making a playlist for…">${esc(state.profile.bio)}</textarea><label>On repeat · pick your favorites</label><p class="small muted">${state.profile.provider?`${esc(state.profile.provider)} demo connected. Favorites are sample data.`:'No music connection needed. Just pick what you like.'}</p>${picker()}<label>What do you make? · optional</label><div class="role-picker">${roles.map(r=>`<button class="chip ${state.profile.roles.includes(r)?'active':''}" type="button" data-action="role" data-role="${r}" aria-pressed="${state.profile.roles.includes(r)}">${r}</button>`).join('')}</div><label for="intent">Open to… · optional</label><input id="intent" name="intent" class="field" maxlength="160" value="${esc(state.profile.intent)}" placeholder="Casual jams, cover art, seeing what happens…"><button type="submit" class="primary">Save my profile ${icon('arrow')}</button><p class="small muted">Creative details help prioritize complementary roles in Create.</p><hr style="border:0;border-top:1px solid var(--line);margin-top:35px"><button class="text-button" type="button" data-action="reset">Reset this demo</button><p class="small muted">This is a fictional demo. Profiles and messages are saved only in this browser. Streaming imports, real accounts, messaging, uploads, and trained recommendations are planned for a future version.</p></form>`;}
function captureProfile(){if(tab==='profile'&&state.joined){const f=document.querySelector('#profile-form');if(f){state.profile.name=f.elements.name.value;state.profile.bio=f.elements.bio.value;state.profile.intent=f.elements.intent.value;}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id);if(a==='home'){e.preventDefault();if(state.joined){tab='people';query='';filter='All people';render();}return;}if(a==='tab'){captureProfile();tab=b.dataset.tab;query='';filter=tab==='create'?'All creatives':'All people';render();document.querySelector('.nav.active')?.focus();window.scrollTo(0,0);}if(a==='provider'){state.profile.provider=b.dataset.provider;state.profile.favorites=b.dataset.provider==='Spotify'?[0,2,5]:[1,4,10];state.joined=true;save();render();toast(`${b.dataset.provider} demo ready — sample favorites added.`);}if(a==='choose'){step=2;onboarding();}if(a==='back-onboard'){step=Math.max(0,step-1);onboarding();}if(a==='join'){state.joined=true;save();render();}if(a==='album'){captureProfile();const p=state.profile.favorites;p.includes(id)?p.splice(p.indexOf(id),1):p.push(id);b.classList.toggle('selected',p.includes(id));b.setAttribute('aria-pressed',p.includes(id));if(state.joined)save();}if(a==='role'){captureProfile();const p=state.profile.roles,r=b.dataset.role;p.includes(r)?p.splice(p.indexOf(r),1):p.push(r);b.classList.toggle('active',p.includes(r));b.setAttribute('aria-pressed',p.includes(r));save();}if(a==='filter'){filter=b.dataset.filter;render();document.querySelector('.chip.active')?.focus();}if(a==='clear'){query='';filter=tab==='create'?'All creatives':'All people';render();}if(a==='member')openMember(id);if(a==='work')openWork(id);if(a==='close')modal.close();if(a==='hey')startChat(id,b.dataset.context);if(a==='thread'){activeChat=id;render();}if(a==='edit-profile'){tab='profile';render();}if(a==='reset'){modal.setAttribute('aria-label','Reset demo');modal.innerHTML=`<h2>A fresh start?</h2><p>This clears your profile and demo conversations from this browser.</p><button class="primary" data-action="confirm-reset">Reset demo</button> <button class="secondary" data-action="close">Keep hanging</button>`;modal.showModal();}if(a==='confirm-reset'){state=defaults();step=0;tab='people';query='';filter='All people';activeChat=null;save();modal.close();render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.querySelector('#results').innerHTML=results();}});
document.addEventListener('change',e=>{if(e.target.id==='role-filter'&&e.target.value){filter=e.target.value;render();}});
document.addEventListener('submit',e=>{if(e.target.id==='name-form'){e.preventDefault();const name=e.target.elements.name.value.trim();if(!name)return;state.profile.name=name;step=1;onboarding();}if(e.target.id==='profile-form'){e.preventDefault();captureProfile();state.profile.name=state.profile.name.trim();if(!state.profile.name){toast('Add a name so people know what to call you.');return;}save();toast('Your corner, updated.');}if(e.target.id==='message-form'){e.preventDefault();const text=e.target.elements.message.value.trim();if(!text)return;const c=state.conversations[activeChat];c.messages.push({from:'me',text});c.messages.push({from:'them',text:c.messages.length===1?'Hey! So glad you reached out. Always down to talk music and make something together. (Demo reply)':'Love that. Let’s keep this idea going! (Demo reply)'});save();render();const messages=document.querySelector('.messages');messages.scrollTop=messages.scrollHeight;document.querySelector('#message').focus();}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
render();
